scwin.goViewer = function (acptNo, formCd, formVer) {
    fn_Disclsviewer(acptNo);
};

/**
 * @method
 * @name allchk
 * @description allchk 처리
 * @returns {void}
 * @hidden N
 */
scwin.allchk = function () {
    let chksize = 0;
    try {
        chksize = $c.util.getComponent('ipt_applNoArr').length;
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00500' }); }
    if (chksize == null || chksize === 1) {
        if ((String($c.util.getComponent('ipt_applNoAll').getValue() || "") !== "")) {
            $c.util.getComponent("ipt_applNoArr").setValue(true);
        } else {
            $c.util.getComponent("ipt_applNoArr").setValue(false);
        }
    } else {
        for (scwin.i = 0; scwin.i < chksize; scwin.i++) {
            if ((String($c.util.getComponent('ipt_applNoAll').getValue() || "") !== "")) {
                $c.util.getComponent('ipt_applNoArr')[scwin.i].checked = true;
            } else {
                $c.util.getComponent('ipt_applNoArr')[scwin.i].checked = false;
            }
        }
    }
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {void}
 * @hidden N
 */
scwin.chk = function () {
    $c.util.getComponent("ipt_applNoAll").setValue(true);
    let chksize = 0;
    try {
        chksize = $c.util.getComponent('ipt_applNoArr').length;
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00500' }); }
    if (chksize == null || chksize === 1) {
        if (!(String($c.util.getComponent('ipt_applNoArr').getValue() || "") !== "")) {
            $c.util.getComponent("ipt_applNoAll").setValue(false);
        }
    } else {
        for (scwin.i = 0; scwin.i < chksize; scwin.i++) {
            if (!$c.util.getComponent('ipt_applNoArr')[scwin.i].checked) {
                $c.util.getComponent("ipt_applNoAll").setValue(false);
                break;
            }
        }
    }
};

/**
 * @method
 * @name enterSearchForm
 * @description enter Search Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterSearchForm = async function () {
    if (event.keyCode === 13) {
        await scwin.searchList();
    }
};

/**
 * @method
 * @name disclosurePreview
 * @description disclosure Preview 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} disclsMaindocFormCd disclsMaindocFormCd
 * @param {*} disclsMaindocFormVer disclsMaindocFormVer
 * @param {String} disclsObjCorpIsurCd disclsObjCorpIsurCd
 * @param {String} langTpCd langTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.disclosurePreview = async function (applNo, docNo, disclsMaindocFormCd, disclsMaindocFormVer, disclsObjCorpIsurCd, langTpCd) {
    $c.util.getComponent('dma_searchListReq').set('applNo', applNo);
    $c.util.getComponent('dma_searchListReq').set('docNo', docNo);
    $c.util.getComponent('dma_searchListReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_searchListReq').set('formCd', disclsMaindocFormCd);
    $c.util.getComponent('dma_searchListReq').set('formVer', disclsMaindocFormVer);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormCd', disclsMaindocFormCd);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormVer', disclsMaindocFormVer);
    $c.util.getComponent('dma_searchListReq').set('isurCd', disclsObjCorpIsurCd);
    $c.util.getComponent('dma_searchListReq').set('langTpCd', langTpCd);
    (document.previewFrm || { elements: [] }).target = 'previewWin';
    (document.previewFrm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosurePreview';
    $c.win.openPopup("", { id: "previewWin", scrollbars: true, resizable: true, width: "835", height: "550", type: "pageFramePopup" }, {});
    await scwin.tx_fn_disclosurePreview();
};
